/**
 * The writer's working bibliography — a flat list of sources saved from
 * the Apparatus panel or discovered by the research provider. Persisted
 * at `/bibliography.json` inside the Lix blob (per folio) so it travels
 * with the manuscript and syncs through the existing Convex pipeline.
 */

import { readFileAsJson, writeFileAsJson } from "./lix";
import type { DetectedCitation, ResearchTargetRef } from "../types";

const BIB_PATH = "/bibliography.json";

export type CitationStyle = "mla" | "apa" | "chicago";

export type BibProvenance = "writer" | "background";

export interface BibEntry {
  id: string;
  folioId: string;
  title: string;
  author?: string;
  publisher?: string;
  date?: string;
  /** Year shortcut for citation builders — mirrors the year inside `date`. */
  year?: string;
  /** DOI if the provider surfaced one. */
  doi?: string;
  url: string;
  accessedAt: number;
  /** Writer's working note — never formatted into the citation. */
  note?: string;
  /** Stable, writer-set key for in-text references (e.g. "smith2024"). */
  citationKey?: string;
  style?: CitationStyle;
  /** Provider-formatted citation text for `style`, when AI formatted the entry. */
  formattedCitation?: string;
  /** The display snippet, if the provider returned one. */
  snippet?: string;
  /** Why this source is relevant to the draft. */
  why?: string;
  /** Optional page hint for MLA in-text citations. */
  pageHint?: string;
  /** Who found this — the writer, or a background agent watching the draft. */
  provenance?: BibProvenance;
  /** The query a background agent was working from (when provenance = "background"). */
  backgroundQuery?: string;
  /** Whether the writer has explicitly accepted a background-saved entry. */
  accepted?: boolean;
  /** The claim/quote/work this source was found for (auto-research). */
  target?: ResearchTargetRef;
  /** Free-form creation timestamp (used by AI-generated entries). */
  createdAt?: number;
}

export async function loadBibliography(): Promise<BibEntry[]> {
  if (typeof window === "undefined") return [];
  try {
    const data = await readFileAsJson<BibEntry[]>(BIB_PATH);
    return Array.isArray(data) ? data : [];
  } catch {
    return [];
  }
}

export async function saveBibliography(bib: BibEntry[]): Promise<void> {
  if (typeof window === "undefined") return;
  try {
    await writeFileAsJson(BIB_PATH, bib);
  } catch {
    // lix unavailable
  }
}

export async function upsertBibEntry(entry: BibEntry): Promise<BibEntry[]> {
  const all = await loadBibliography();
  const idx = all.findIndex((e) => e.id === entry.id);
  if (idx >= 0) all[idx] = entry;
  else all.push(entry);
  await saveBibliography(all);
  return all;
}

export async function deleteBibEntry(id: string): Promise<BibEntry[]> {
  const all = await loadBibliography();
  const next = all.filter((e) => e.id !== id);
  await saveBibliography(next);
  return next;
}

/* ── Citation formatters (MLA / APA / Chicago) ────────────────── */

function mlaEscape(s: string | undefined): string {
  if (!s) return "";
  return s.replace(/\s+/g, " ").trim();
}

export function formatMla(e: BibEntry): string {
  const parts: string[] = [];
  const author = mlaEscape(e.author);
  if (author) parts.push(`${author}.`);
  parts.push(`"${mlaEscape(e.title)}."`);
  if (e.publisher) parts.push(`${mlaEscape(e.publisher)},`);
  if (e.date) parts.push(`${mlaEscape(e.date)},`);
  if (hasResolvableUrl(e.url)) {
    parts.push(formatUrlAccessed(e.url, e.accessedAt) + ".");
  }
  return parts.join(" ");
}

export function formatApa(e: BibEntry): string {
  const parts: string[] = [];
  const author = mlaEscape(e.author);
  const date = e.date ?? e.year;
  if (author) parts.push(`${author} (${date ?? "n.d."}).`);
  else if (date) parts.push(`(${date}).`);
  parts.push(`${mlaEscape(e.title)}.`);
  if (e.publisher) parts.push(`${mlaEscape(e.publisher)}.`);
  if (e.url) parts.push("Retrieved from " + e.url);
  return parts.join(" ");
}

export function formatChicago(e: BibEntry): string {
  const parts: string[] = [];
  const author = mlaEscape(e.author);
  if (author) parts.push(`${author}.`);
  parts.push(`"${mlaEscape(e.title)}."`);
  if (e.publisher) parts.push(`${mlaEscape(e.publisher)}.`);
  if (e.date ?? e.year) parts.push(`${mlaEscape(e.date ?? e.year)}.`);
  if (e.url) parts.push(e.url + ".");
  parts.push(`Accessed ${new Date(e.accessedAt).toLocaleDateString()}.`);
  return parts.join(" ");
}

export function formatCitation(e: BibEntry, style: CitationStyle): string {
  if (e.formattedCitation && e.style === style) {
    return e.formattedCitation;
  }
  switch (style) {
    case "mla":
      return formatMla(e);
    case "apa":
      return formatApa(e);
    case "chicago":
      return formatChicago(e);
  }
}

function formatUrlAccessed(url: string, ts: number): string {
  try {
    const u = new URL(url);
    return `${u.hostname.replace(/^www\./, "")} · accessed ${new Date(ts).toLocaleDateString()}`;
  } catch {
    return `${url} · accessed ${new Date(ts).toLocaleDateString()}`;
  }
}

/* ── A one-liner the writer can drop in a footnote ───────────── */

export function footnoteCite(e: BibEntry, style: CitationStyle): string {
  const author = mlaEscape(e.author) || "Anonymous";
  const year = e.year ?? e.date?.match(/\d{4}/)?.[0] ?? "n.d.";
  switch (style) {
    case "apa":
    case "chicago":
      return `(${author.split(",")[0]}, ${year})`;
    case "mla":
      return `(${author.split(",")[0]} ${e.pageHint ?? ""})`.trim();
  }
}

/* ── Dedup helpers ──────────────────────────────────────────────── */

/** Normalize a URL for dedupe — strips trailing slashes, lowercases host. */
export function normalizeUrl(u: string): string {
  try {
    const x = new URL(u);
    return `${x.host.toLowerCase().replace(/^www\./, "")}${x.pathname}`.replace(
      /\/+$/,
      "",
    );
  } catch {
    return u.replace(/\/+$/, "").toLowerCase();
  }
}

export function hasResolvableUrl(url: string | undefined | null): boolean {
  return typeof url === "string" && url.trim().length > 0;
}

export async function findBibByUrl(url: string): Promise<BibEntry | undefined> {
  if (!hasResolvableUrl(url)) return undefined;
  const target = normalizeUrl(url);
  const all = await loadBibliography();
  return all.find((e) => normalizeUrl(e.url) === target);
}

export async function mergeBibEntry(entry: BibEntry): Promise<BibEntry[]> {
  if (!hasResolvableUrl(entry.url)) {
    return upsertBibEntry(entry);
  }
  const existing = await findBibByUrl(entry.url);
  if (existing) {
    return upsertBibEntry({ ...existing, ...entry, id: existing.id });
  }
  return upsertBibEntry(entry);
}

export interface FormattedCitationFields {
  title: string;
  author?: string;
  year?: string;
  date?: string;
  url?: string;
  doi?: string;
  publisher?: string;
  formatted?: string;
  style?: CitationStyle;
}

function stableCitationId(folioId: string, citation: DetectedCitation): string {

/**
 * Push the full local-state payload from the browser to the server.
 * Used on sign-up (when the user has local data and no remote data) and
 * after every subsequent local change (debounced).
 */
export const pushAll = mutation({
  args: {
    briefs: v.optional(
      v.array(v.object({ folioId: v.string(), brief: v.any() })),
    ),
    folios: v.optional(v.array(v.any())),
    folioContent: v.optional(
      v.array(v.object({ folioId: v.string(), html: v.string() })),
    ),
    customPersonas: v.optional(v.array(v.any())),
    personaNotes: v.optional(
      v.array(
        v.object({
          folioId: v.string(),
          noteId: v.string(),
          personaId: v.string(),
          personaName: v.string(),
          personaColor: v.string(),
          type: v.string(),
          feedback: v.string(),
          anchor: v.optional(v.string()),
          briefTitle: v.optional(v.string()),
          createdAt: v.number(),
        }),
      ),
    ),
    personaReplies: v.optional(
      v.array(
        v.object({
          folioId: v.string(),
          replyId: v.string(),
          noteId: v.string(),
          author: v.string(),
          authorKind: v.string(),
          personaId: v.optional(v.string()),
          text: v.string(),
          createdAt: v.number(),
        }),
      ),
    ),
    rubricResults: v.optional(
      v.array(v.object({ folioId: v.string(), result: v.any() })),
    ),
    bibliography: v.optional(v.array(v.any())),
  },
  handler: async (ctx, args) => {
    const userId = await requireIdentity(ctx);
    const now = Date.now();

    if (args.briefs) {
      for (const dossier of args.briefs) {
        const existing = await ctx.db
          .query("briefs")
          .withIndex("by_userId_folioId", (q) =>
            q.eq("userId", userId).eq("folioId", dossier.folioId),
          )
          .first();
        if (existing) {
          await ctx.db.patch(existing._id, {
            brief: dossier.brief,
            updatedAt: now,
          });
        } else {
          await ctx.db.insert("briefs", {
            userId,
            folioId: dossier.folioId,
            brief: dossier.brief,
            updatedAt: now,
          });
        }
      }
    }

    if (args.folios !== undefined) {
      const existing = await ctx.db
        .query("folios")
        .withIndex("by_userId", (q) => q.eq("userId", userId))
        .first();
      if (existing) {
        await ctx.db.patch(existing._id, {
          folios: args.folios,
          updatedAt: now,
        });
      } else {
        await ctx.db.insert("folios", {
          userId,
          folios: args.folios,
          updatedAt: now,
        });
      }
    }

    if (args.folioContent) {
      for (const fc of args.folioContent) {
        const existing = await ctx.db
          .query("folioContent")
          .withIndex("by_userId_folioId", (q) =>
            q.eq("userId", userId).eq("folioId", fc.folioId),
          )
          .first();
        if (existing) {
          await ctx.db.patch(existing._id, {
            html: fc.html,
            updatedAt: now,
          });
        } else {
          await ctx.db.insert("folioContent", {
            userId,
            folioId: fc.folioId,
            html: fc.html,
            updatedAt: now,
          });
        }
      }
    }

    if (args.customPersonas !== undefined) {
      const existing = await ctx.db
        .query("customPersonas")
        .withIndex("by_userId", (q) => q.eq("userId", userId))
        .first();
      if (existing) {
        await ctx.db.patch(existing._id, {
          personas: args.customPersonas,
          updatedAt: now,
        });
      } else {
        await ctx.db.insert("customPersonas", {
          userId,
          personas: args.customPersonas,
            result: rubric.result,
            updatedAt: now,
          });
        } else {
          await ctx.db.insert("rubricResults", {
            userId,
            folioId: rubric.folioId,
            result: rubric.result,
            updatedAt: now,
          });
        }
      }
    }

    if (args.bibliography !== undefined) {
      const existing = await ctx.db
        .query("bibliographies")
        .withIndex("by_userId", (q) => q.eq("userId", userId))
        .first();
      if (existing) {
        await ctx.db.patch(existing._id, {
          entries: args.bibliography,
          updatedAt: now,
        });
      } else {
        await ctx.db.insert("bibliographies", {
          userId,
          entries: args.bibliography,
          updatedAt: now,
        });
      }
    }

    return { ok: true, syncedAt: now };
  },
});

/**
 * Pull the full user state in a single round-trip. The browser calls
 * this on sign-in to hydrate; it then merges the result with whatever
 * was already in IndexedDB (newer-wins by `updatedAt`).
 */
export const pullAll = query({
  args: {},
  handler: async (ctx) => {
    const userId = await requireIdentity(ctx);

    const [
      briefs,
      folios,
      folioContent,
      customPersonas,
      personaNotes,
      personaReplies,
      rubricResults,
      bibliography,
    ] = await Promise.all([
      ctx.db
        .query("briefs")
        .withIndex("by_userId", (q) => q.eq("userId", userId))
        .collect(),
      ctx.db
        .query("folios")
        .withIndex("by_userId", (q) => q.eq("userId", userId))
        .first(),
      ctx.db
        .query("folioContent")
        .withIndex("by_userId", (q) => q.eq("userId", userId))
        .collect(),
      ctx.db
        .query("customPersonas")
        .withIndex("by_userId", (q) => q.eq("userId", userId))
        .first(),
      ctx.db
        .query("personaNotes")
        .withIndex("by_userId", (q) => q.eq("userId", userId))
        .collect(),
      ctx.db
        .query("personaReplies")
        .withIndex("by_userId", (q) => q.eq("userId", userId))
        .collect(),
      ctx.db
        .query("rubricResults")
        .withIndex("by_userId", (q) => q.eq("userId", userId))
        .collect(),
      ctx.db
        .query("bibliographies")
        .withIndex("by_userId", (q) => q.eq("userId", userId))
        .first(),
    ]);

    return {
      briefs: briefs
        .filter((row) => row.folioId)
        .map((row) => ({
          folioId: row.folioId!,
          brief: row.brief,
          updatedAt: row.updatedAt,
        })),
      legacyBrief:
        briefs.find((row) => row.folioId === undefined)?.brief ?? null,
      legacyBriefUpdatedAt:
        briefs.find((row) => row.folioId === undefined)?.updatedAt ?? 0,
      folios: folios?.folios ?? [],
      foliosUpdatedAt: folios?.updatedAt ?? 0,
      folioContent: folioContent.map((fc) => ({
        folioId: fc.folioId,
        html: fc.html,
        updatedAt: fc.updatedAt,
      })),
      customPersonas: customPersonas?.personas ?? null,
      customPersonasUpdatedAt: customPersonas?.updatedAt ?? 0,
      personaNotes: personaNotes.map((n) => ({
        folioId: n.folioId,
        noteId: n.noteId,
        personaId: n.personaId,
        personaName: n.personaName,
        personaColor: n.personaColor,
        type: n.type,
        feedback: n.feedback,
        anchor: n.anchor,
        briefTitle: n.briefTitle,
        createdAt: n.createdAt,
      })),
      personaReplies: personaReplies.map((r) => ({
        folioId: r.folioId,
        replyId: r.replyId,
        noteId: r.noteId,
        author: r.author,
        authorKind: r.authorKind,
        personaId: r.personaId,
        text: r.text,
        createdAt: r.createdAt,
      })),
      rubricResults: rubricResults.map((rubric) => ({
        folioId: rubric.folioId,
        result: rubric.result,
        updatedAt: rubric.updatedAt,
      })),
      bibliography: bibliography?.entries ?? [],
      bibliographyUpdatedAt: bibliography?.updatedAt ?? 0,
    };
  },
});

